import csv
import io
import re

_EXPECTED_COLUMNS = [
    "DATE",
    "TIME",
    "Qty",
    "PRODUCTID",
    "Price",
    "ProductType",
    "ProductDescription",
    "URL",
    "Comments",
]
_EXPECTED_WIDTH = 9


def _clean_name(value):
    return value.lstrip("\ufeff").strip()


def _is_header(row):
    if len(row) < _EXPECTED_WIDTH:
        return False
    normalized = [re.sub(r"[^a-z0-9]+", "", _clean_name(v).lower()) for v in row[:_EXPECTED_WIDTH]]
    expected = [re.sub(r"[^a-z0-9]+", "", v.lower()) for v in _EXPECTED_COLUMNS]
    return normalized == expected


def _find_header_offset(raw_csv):
    offset = 0
    for line in raw_csv.splitlines(keepends=True):
        try:
            parsed = next(csv.reader([line], delimiter=",", quotechar='"'))
        except (csv.Error, StopIteration):
            parsed = []
        if _is_header(parsed):
            return offset
        offset += len(line)
    return None


def _is_url(value):
    return re.match(r"^\s*(?:https?://|ftp://|www\.)", value, re.IGNORECASE) is not None


def _normalize_row(row):
    row = ["" if value is None else str(value) for value in row]

    url_index = None
    for index in range(5, len(row)):
        if _is_url(row[index]):
            url_index = index
            break

    if url_index is not None:
        left = row[:url_index]
        url = row[url_index]
        comments = ",".join(row[url_index + 1:])

        fixed = left[:5]
        while len(fixed) < 5:
            fixed.append("")

        product_type = left[5] if len(left) > 5 else ""
        description = ",".join(left[6:]) if len(left) > 6 else ""
        return fixed + [product_type, description, url, comments]

    if len(row) == _EXPECTED_WIDTH:
        return row

    if len(row) > _EXPECTED_WIDTH:
        return row[:6] + [",".join(row[6:-2])] + row[-2:]

    return row + [""] * (_EXPECTED_WIDTH - len(row))


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    try:
        csv.field_size_limit(2147483647)
    except (OverflowError, csv.Error):
        try:
            csv.field_size_limit(100000000)
        except (OverflowError, csv.Error):
            pass

    header_offset = _find_header_offset(raw_csv)
    source = raw_csv[header_offset:] if header_offset is not None else raw_csv

    reader = csv.reader(
        io.StringIO(source, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        skipinitialspace=False,
        strict=False,
    )

    records = []
    try:
        records = list(reader)
    except csv.Error:
        records = []

    header_index = None
    for index, row in enumerate(records):
        if _is_header(row):
            header_index = index
            break

    if header_index is not None:
        header = records[header_index][:_EXPECTED_WIDTH]
        header[0] = header[0].lstrip("\ufeff")
        data_rows = records[header_index + 1:]
    elif records:
        header = _normalize_row(records[0])
        header[0] = header[0].lstrip("\ufeff")
        data_rows = records[1:]
    else:
        header = list(_EXPECTED_COLUMNS)
        data_rows = []

    if len(header) < _EXPECTED_WIDTH:
        header += _EXPECTED_COLUMNS[len(header):]
    elif len(header) > _EXPECTED_WIDTH:
        header = header[:_EXPECTED_WIDTH]

    rows = [_normalize_row(row) for row in data_rows]
    return {"columns": header, "rows": rows}
